from pages import *
from fig import *
i=12
def display(w=300,n=7,s=1):
    o=g(0,0,1,steps(n,w,n*22))
    for r in range(n):
        for c in range(max(1,n-r-1)):
            ww=w-r*(w/(n+1)); x=-ww/2+16+c*((ww-32)/max(1,n-r-2) if n-r-2>0 else 0)
            col=['#c0392b','#1d6fb8','#2a9d6f','#e0a800','#7a3fa0','#ff8c1a'][(r+c)%6]
            o+=g(x if n-r-1>1 else 0,-r*22,.5,doll(col,crown=(r>=n-2)))
    return o
COV=covart('Doll steps covered in white cloth with rows of colourful dolls, a royal wooden doll couple at the top, lamps on either side',g(220,196,1.05,display(320,7))+g(220,196-7*22,.9,doll('#a8553a','#e0a800'))+g(60,196,1,lamp())+g(380,196,1,lamp()))
pages=[foreword(i,['The nine Durgās are done. Now we come back to the evenings of a Karnataka home, and to the most loved Navarātri custom of old Mysuru: the <b>Gombe Habba</b> (or <b>Bombe Habba</b>), the festival of dolls.','For nine days a staircase of dolls fills a corner of the house: gods at the top, the royal couple in pride of place, scenes of village life, weddings and epics below. Neighbours come to see, children sing, and every guest leaves with a small gift.'],
 [('z','Is it just for children?'),('b','Children love it most, but it is a whole household’s project, and for many families an heirloom handed down for generations.')]),
 glance([('Names','Gombe Habba or Bombe Habba (Karnataka); Golu or Kolu (Tamil Nadu); Bommala Koluvu (Andhra)'),('When','Set up at the start of Navarātri; taken down after Vijayadaśamī'),('The steps','An odd number of tiers (3, 5, 7, 9 or 11), often covered with white cloth; nine is common'),('The heart of it','The paṭṭada gombe: a wooden king-and-queen doll pair, often an heirloom'),('Top tiers','Gods and goddesses; below them saints, people, animals, scenes'),('Evenings','Visits, songs, and a gift of turmeric, kuṅkuma and something sweet'),('Where strongest','Old Mysuru, and across South India')],svg(560,170,'A small doll display with seven tiers',g(280,165,1,display(260,7)))),
 reading('what','WHAT IT IS','A staircase of the whole world',svg(560,220,'A tall doll display on white-covered steps with gods at the top, a royal couple in the middle and village scenes at the bottom, with labels',g(280,210,1.4,display(330,7))+lab(470,40,'gods and goddesses')+lab(470,110,'saints and epics')+lab(470,190,'village and daily life')),[
  '<b>The display.</b> A wooden stand or a set of planks makes steps, usually an odd number. It is covered with a white or light cloth, and dolls are arranged on it tier by tier.','<b>An order.</b> The usual order goes from heaven to earth: deities at the top; saints, sages and epic scenes in the middle; people, animals, trees, markets and village life at the bottom. Many read it as creation itself, from the divine down to the everyday.','<b>Made of many things.</b> Dolls are of clay, wood, papier-mâché, brass or cloth. Old families have pieces a century old; new ones are added every year.','<b>A theme.</b> Many families build a theme each year: the Daśāvatāra, the Rāmāyaṇa, a wedding, a temple festival, even a cricket match. Creativity is part of the devotion.'],
  [('z','So you can put anything on the steps?'),('b','Within the order: gods on top, always. After that, the world. A good display tells a story.')],'Odd steps, gods at the top, the world below: <b>a staircase of creation</b>.'),
 reading('pattada','THE PAṬṬADA GOMBE','The royal doll couple',svg(560,200,'A pair of carved red wooden dolls, a king and queen in silk clothes and gold crowns, placed side by side on a small platform',g(240,180,2.4,doll('#a8553a','#e0a800'))+g(320,180,2.4,doll('#c0392b','#e0a800'))+'<rect x="180" y="180" width="200" height="12" fill="#e8c06a" stroke="#111" stroke-width="2"/>'+lab(240,40,'Rāja')+lab(320,40,'Rāṇi')),[
  '<b>The pair.</b> At the heart of every Karnataka display is the <b>paṭṭada gombe</b>, a pair of dolls, a king and queen or husband and wife. Traditionally they are carved from red sandalwood or rosewood, and dressed in fresh clothes each year.','<b>From mother to daughter.</b> Parents give a pair to their daughter at her wedding, so that she can begin her own collection in her new home. Many pairs are generations old.','<b>Why a royal couple.</b> A common explanation in Mysuru links them to the Mahārāja: he was bound by his Navarātri vows to the palace and could not visit homes, so households honoured a doll king and queen in his place. Other families read the pair simply as the divine couple, Śiva and Śakti. Sources differ, and we give both.','<b>Pride of place.</b> The pair sits high on the steps, just below or among the gods, and is the last to be put away.'],
  [('z','So the dolls are like the king and queen?'),('b','In old Mysuru, yes: a little palace in every home. For others they are the divine couple. Either way, they are the family’s treasure.')],'The paṭṭada gombe: <b>a wooden royal couple, handed down from mother to daughter</b>.'),
 cards('steps','THE STEPS, TIER BY TIER','A typical arrangement',svg(560,200,'A side view of seven numbered steps with a sample doll on each',''.join(f'<rect x="{60+k*60}" y="{170-k*20}" width="{460-k*60}" height="20" fill="#fff8ec" stroke="#111" stroke-width="1.5"/>'+lab(80+k*60,183-k*20,str(k+1),11) for k in range(7))+''.join(g(110+k*60,170-k*20,.55,doll(['#2a9d6f','#e0a800','#7a3fa0','#ff8c1a','#c0392b','#a8553a','#1d6fb8'][k])) for k in range(7))),[
  ('🛕','Top: the gods','Gaṇeśa first, then the Devī, Lakṣmī, Sarasvatī, Viṣṇu, Śiva, often the Daśāvatāra set.'),('👑','Next: the royal couple and saints','The paṭṭada gombe; saints and sages; a kalaśa or temple scene.'),('📜','Middle: epics and festivals','Rāma’s coronation, Kṛṣṇa’s childhood, a wedding procession, a temple car.'),('🌳','Bottom: the world','Merchants, farmers, animals, trees, a market, a school: everyday life blessed by what is above.')],
  [('z','Is there a rule for the number of steps?'),('b','Odd numbers, by custom: 3, 5, 7, 9 or 11. Nine is popular because of the nine nights.')],'Gods above, the world below, <b>every tier in its place</b>.'),
 reading('history','HOW IT CAME TO MYSURU','Theories and memories',svg(560,180,'An old palace with lamps and, in front, a family carrying dolls into a house',g(150,170,.9,palace())+g(380,170,1,person('#c0392b'))+g(400,140,.6,doll())+g(440,170,1,person('#1d6fb8'))+'<rect x="470" y="90" width="70" height="80" fill="#f3e3c3" stroke="#111" stroke-width="2"/>'),[
  '<b>Old and royal.</b> Families in old Mysuru tie the custom to the royal Dasarā of the Woḍeyars, and some date it as far back as Raja Woḍeyar’s time. Writers on Mysuru say the tradition reached its height under the last Woḍeyar kings.','<b>A recent form?</b> Other researchers think the present form of the display is more recent, perhaps from around the 18th century, and note that many clay dolls still come from traditional doll-making towns, including outside Karnataka.','<b>A shared South Indian custom.</b> Tamil Nadu’s Golu and Andhra’s Bommala Koluvu are the same tradition; scholars see the doll display spreading across the south with Navarātri.','<b>Revival.</b> In the late 20th century the custom declined in busy city homes, and many families and groups in Mysuru and Bengaluru now hold open “bombe mane” (doll house) displays to keep it alive.'],
  [('z','So nobody knows exactly when it started?'),('b','Not for sure. Families remember; historians argue. Both agree it belongs to Mysuru’s Dasarā.')],'Royal Mysuru memories, scholars’ doubts, <b>a living South Indian custom</b>.'),
 reading('visits','EVENINGS OF VISITING','Songs, guests and the gift of turmeric',svg(560,190,'Women and children visiting a home with a doll display, a hostess offering a plate with turmeric, kuṅkuma, betel leaves and a sweet',ground(560,190,170,'#e9d6c0')+g(120,170,.8,display(160,5))+g(300,170,1,person('#c0392b'))+g(330,130,.7,'<ellipse rx="26" ry="6" fill="#e0a800"/><circle cx="-10" cy="-4" r="4" fill="#ffd60a"/><circle cx="2" cy="-4" r="4" fill="#c0392b"/>')+g(420,170,1,person('#2a9d6f'))+g(470,170,.8,child())+g(500,170,.8,child())),[
  '<b>Invitations.</b> Through the nine evenings, women and children go from house to house to see each family’s display. Hosts often invite friends especially.','<b>Songs.</b> Visitors, especially girls, are asked to sing a devotional song or a verse before the dolls: an easy stage for young singers.','<b>The gift.</b> Each guest receives <b>arishina-kuṅkuma</b> (turmeric and kuṅkuma), often with betel leaves, a fruit or a sweet, and sometimes a small gift. The details differ by family.','<b>The snack.</b> A small dish, often <i>usli</i> (seasoned boiled lentils, the Tamil sundal) or a sweet, is served each evening.'],
  [('z','Why turmeric and kuṅkuma?'),('b','They are the marks of auspicious married life and blessing. Giving them to guests is giving the Goddess’s blessing on.')],'Visits, songs and turmeric: <b>the Goddess’s blessing passed from home to home</b>.'),
 cards('themes','STORIES IN DOLLS','Favourite themes',svg(560,170,'Four small doll scenes: the ten avatāras in a row, Rāma’s coronation, a wedding, and a village market',''.join(g(30+k*13,90,.32,doll(['#1d6fb8','#2a9d6f'][k%2])) for k in range(10))+g(240,150,.5,doll('#2a9d6f'))+g(260,150,.5,doll('#c0392b'))+g(360,150,.5,doll('#c0392b'))+g(380,150,.5,doll('#e0a800'))+''.join(g(460+k*20,150,.4,doll('#a8553a',crown=False)) for k in range(4))+lab(90,120,'Daśāvatāra')+lab(250,170,'Rāma’s court')+lab(370,170,'a wedding')+lab(490,170,'the market')),[
  ('🐟','The Daśāvatāra','Viṣṇu’s ten avatāras in a row, from Matsya to Kalki: a favourite top-tier set (see our <a href="/vishnu/dashavatara/">Daśāvatāra series</a>).'),('🏹','The Rāmāyaṇa','Rāma’s coronation (paṭṭābhiṣeka) or scenes from the epic, often with Hanumān kneeling.'),('💍','A wedding','A full wedding procession, with musicians, the couple and the feast: dolls for a family that has had a wedding that year.'),('🏘️','Village and town','Farmers, a market, a school, a temple car: the world the gods look after.')],
  [('z','Can we put modern things in?'),('b','Many families do: trains, cricket, astronauts. The gods stay on top; the world below keeps changing.')],'Epics, weddings, villages: <b>every year a new story</b>.'),
 reading('south','ACROSS SOUTH INDIA','Golu, Kolu, Bommala Koluvu',svg(560,180,'A simplified map of South India with doll icons in Karnataka, Tamil Nadu and Andhra Pradesh',
  '<path d="M200 10 l120 0 l40 50 l-10 60 l-50 50 l-30 0 l-40 -60 l-40 -50z" fill="#f3e3c3" stroke="#111" stroke-width="2.5"/>'+g(230,80,.6,doll())+g(300,140,.6,doll('#1d6fb8'))+g(320,50,.6,doll('#2a9d6f'))+lab(170,80,'Gombe Habba')+lab(380,140,'Golu / Kolu')+lab(400,50,'Bommala Koluvu')+lab(480,175,'simplified, not to scale',9)),[
  '<b>Tamil Nadu: Golu.</b> The <b>Golu</b> or <b>Kolu</b> display is central to Tamil Navarātri, with a sacred kalaśa often placed on the steps, and evenings of songs and sundal. Its key pair, the <b>marapācci</b> dolls, are the Tamil cousins of the paṭṭada gombe.','<b>Andhra and Telangana: Bommala Koluvu.</b> The same steps and dolls, with their own local favourites.','<b>Kerala.</b> Some communities, especially Tamil-origin families, keep a Kolu; Kerala’s own Navarātri focus is on Sarasvatī and Vidyārambha.','<b>One custom.</b> Across the south the essentials are the same: odd steps, gods above, a beloved doll couple, visits, songs and gifts.'],
  [('z','So my Tamil friend has the same festival?'),('b','The same steps with a different name. Visit each other’s displays; that is the point.')],'Gombe, Golu, Bommala Koluvu: <b>one doll festival, three languages</b>.'),
 reading('close','PUTTING THE DOLLS TO SLEEP','How the display ends',svg(560,170,'A doll couple being laid down to rest in a box lined with cloth, with a lamp beside',g(220,140,1,'<rect x="-80" y="-20" width="160" height="40" fill="#a8553a" stroke="#111" stroke-width="2"/><rect x="-74" y="-16" width="148" height="32" fill="#fde4e4"/>')+g(200,126,1.3,'<g transform="rotate(90)">'+doll('#a8553a')+'</g>')+g(240,126,1.3,'<g transform="rotate(90)">'+doll('#c0392b')+'</g>')+g(420,150,1,lamp())),[
  '<b>The last evening.</b> On Vijayadaśamī, after the day’s worship, an ārati is done before the dolls and a final offering made.','<b>Laying them down.</b> In many Karnataka homes the paṭṭada gombe are gently laid down, as if going to sleep, marking the end of the festival; some families say a small prayer that they will rise again next year.','<b>Packing away.</b> Over the next day the dolls are wrapped and packed, often in the same boxes and cloths as every year, ready for the next Navarātri.','<b>A year’s rest.</b> Many say the house feels empty for a while. That emptiness is part of the joy of the next year’s return.'],
  [('z','Why lay them down instead of just packing them?'),('b','Because they have been guests and family for nine nights. You don’t throw a guest in a box; you say goodbye.')],'Laid down to sleep after Vijayadaśamī: <b>until next year</b>.'),
 end(i,['<b>What.</b> A staircase of dolls, odd steps, gods at the top.','<b>Heart.</b> The paṭṭada gombe, a royal couple, handed from mother to daughter.','<b>Evenings.</b> Visits, songs and the gift of turmeric and kuṅkuma.','<b>Across the south.</b> Golu and Bommala Koluvu: the same custom.','<b>End.</b> The dolls are laid down after Vijayadaśamī.'],'Part 14 takes us to the last days: Sarasvatī Pūjā, when books are given to the Goddess, and Durgāṣṭamī.','Gombe Habba'),
 sources([('Custom:','Karnataka Tourism, “Gombe Habba”; Karnataka.com, “Dasara Doll Festival” (odd steps, paṭṭada gombe as a wedding gift); Wikipedia, “Golu (festival)”.'),('Mysuru:','Deccan Herald features on Mysuru doll displays (royal links, decline and revival, possible 18th-century origin); Bindu Gopal Rao, “Bombe Habba” (the Mahārāja theory, red sandalwood).')],'the origin and date of the custom (theories differ); the royal-proxy explanation of the paṭṭada gombe; the names of gifts and snacks (vary by family).','Customs described in their common Mysuru form.')]
build(i,'PART 13 OF 16 · DOLLS · STEPS · VISITS',COV,'The doll steps of old Mysuru',
 'What a <b>doll display</b> is, the <b>royal doll couple</b>, the steps tier by tier, how it came to Mysuru, the <b>evenings of visiting</b>, and how the dolls are put to sleep.',
 'Gombe Habba (Bombe Habba), the Navarātri doll festival of Karnataka: the stepped display, the paṭṭada gombe royal couple, how it came to Mysuru, evenings of visiting and the gift of turmeric and kuṅkuma, Golu and Bommala Koluvu across South India, and putting the dolls to sleep. Part 13 of the illustrated Navarātri series.',pages)
